function trasforma(input){
  var n = function(s){ return parseFloat(String(s).replace(/\./g, '').replace(',', '.')); };
  var t = input.Righe.reduce(function(a, r){ return a + n(r.Quantita) * n(r.PrezzoUnitario); }, 0);
  if (input.Sconto) t = t * (1 - n(String(input.Sconto).replace('%', '')) / 100);
  return { totale_righe: Math.round(t * 100) / 100 };
}

ref_py:
def trasforma(campi):
    n = lambda s: float(str(s).replace('.', '').replace(',', '.'))
    t = sum(n(r['Quantita']) * n(r['PrezzoUnitario']) for r in campi['Righe'])
    if campi.get('Sconto'):
        t *= 1 - n(str(campi['Sconto']).replace('%', '')) / 100
    return {'totale_righe': round(t, 2)}
